from robot.api import logger
import subprocess
import time
import sys


projects_urls = {'taf.rfrl.procedures': 'git@wrgitlab.ext.net.nokia.com/RAN/resource-packages/taf.rfrl.procedures.git',
                 'taf.ul.bts_components': 'git@wrgitlab.ext.net.nokia.com/TAF/taf.ul.bts_components.git',
                 'taf.rfrl.l3_call': 'git@wrgitlab.ext.net.nokia.com/RAN/resource-packages/taf.rfrl.l3_call.git'}


def get_pybot_variable_for_project(project_name):
    """
    Gets global pybot variable name based on taf library project name.

    :param project_name: taf project name, e.g.: 'taf.rfrl.procedures'
    :type project_name: str

    :return: global pybot variable name for given taf project name, e.g.: 'TAF_RFRL_PROCEDURES'
    :rtype: str
    """
    return project_name.replace(".", "_").upper()


def branch_installer(project_name, project_url, branch_name):
    """
    Performs pip upgrade of particular taf library from given branch name.
    Installer prints log warning when library has been upgraded successfully.
    Installer prints log error when library could not be installed successfully. Log error will not fail test results.

    :param project_name: taf project name, e.g.: 'taf.rfrl.procedures'
    :type project_name: str
    :param project_url: taf project url, e.g.: 'https://wrgitlab.ext.net.nokia.com/RAN/resource-packages/taf.rfrl.procedures'
    :type project_url: str
    :param branch_name: taf project branch name, e.g.: 'develop'
    :type branch_name: str
    """
    pip_cmd = [sys.executable, "-m", "pip", "install", "--force-reinstall", "--no-deps", "-U", f"git+ssh://{project_url}@{branch_name}"]
    try:
        subprocess.check_call(pip_cmd)
        logger.warn(f"Library '{project_name}' has been upgraded to '{branch_name}' branch. "
                    f"Be aware that some functionalities could not work properly!")
        time.sleep(5)
    except subprocess.CalledProcessError:
        logger.error(f"Upgrade of '{project_name}' library to '{branch_name}' branch has failed.")
        raise


def add_gitlab_host_to_ssh_config():
    """
    Modifies the /home/ute/.ssh/config file on the VM by adding a new host:

    Host wrgitlab.ext.net.nokia.com
        IdentityFile ~/.ssh/ca_ute_gitlab/id_rsa
        User ca_ute_gitlab
    """
    gitlab_host = """Host wrgitlab.ext.net.nokia.com
        IdentityFile ~/.ssh/ca_ute_gitlab/id_rsa
        User ca_ute_gitlab"""

    with open("/home/ute/.ssh/config", "r+") as f:
        current_config = f.read()

        if gitlab_host not in current_config:
            f.seek(0, 2)
            f.write(f"\n{gitlab_host}\n\n")
        else:
            logger.info("Modification of ssh config is not needed. Host already exists.")
